-- Importação orçamento 2026 — BG2026.Template_BR
-- Gerado automaticamente por Claude
-- ========================================================

-- 1. Unidades

-- 2. Categorias

-- 3. Limpar budget_lines 2026 (reimport)
DELETE FROM public.budget_lines WHERE year = 2026;

-- 4. Inserir budget_lines 2026

-- Resumo
SELECT u.name AS unidade, c.name AS categoria, COUNT(*) AS linhas, SUM(bl.value) AS total_brl
FROM public.budget_lines bl
JOIN public.units u ON u.id = bl.unit_id
JOIN public.categories c ON c.id = bl.category_id
WHERE bl.year = 2026
GROUP BY u.name, c.name
ORDER BY SUM(bl.value) DESC;